// One item per city. /points is called for every city even when the grid is
// already cached: it is free (no rate limit), it returns the AUTHORITATIVE
// forecast URL rather than one we assembled by hand, and it re-heals the
// cache when NWS re-grids a location.
const cfg = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json).flat();
const cap = Number(cfg.max_cities_per_run || 0) || 0;

const out = [];
for (const c of cities) {
  if (!c || !c.city_key) continue;
  if (c.nws_supported === false) continue;      // proven non-US by an earlier run
  if (c.latitude == null || c.longitude == null) continue;

  const lat = Number(c.latitude).toFixed(4);
  const lon = Number(c.longitude).toFixed(4);
  out.push({ json: {
    city_key: c.city_key,
    grid_wfo: c.nws_grid_wfo ?? null,
    grid_x: c.nws_grid_x ?? null,
    grid_y: c.nws_grid_y ?? null,
    point_url: `https://api.weather.gov/points/${lat},${lon}`,
  }});
  if (cap && out.length >= cap) break;
}
if (out.length === 0) {
  throw new Error('No cities with coordinates. NWS forecasts are addressed by ' +
                  'lat/lon - check cities.latitude / longitude are populated.');
}
return out;

// Pair each /points response back to the city that asked for it, and take the
// hourly forecast URL NWS itself published.
const reqs = $('Build requests').all().map(i => i.json);
// THE BUG THAT MADE ALL 37 CITIES "FAIL".
// n8n's HTTP node autodetects the response format from Content-Type, and its
// test is `contentType.includes('application/json')`. api.weather.gov answers
// `application/geo+json` (and `application/problem+json` on an error), neither
// of which contains that substring - so every response was decoded as TEXT and
// arrived as `{ data: "{\"properties\":..." }`. No `properties`, no `status`,
// no `title`: not a 404, not an error, just nothing to read. Hence "0 are not
// US, 37 failed" with no detail to report, in both P1.2 and P1.3, forever.
// The Fetch nodes now set responseFormat=json explicitly. This re-parses a
// string body regardless, so the workflow also works on an n8n build that
// names that option differently.
function asJson(v) {
  if (v == null) return {};
  if (typeof v === 'string') {
    const s = v.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
    return { error: 'unparseable body: ' + s.slice(0, 200) };
  }
  if (typeof v !== 'object') return {};
  if (typeof v.data === 'string') {
    const s = v.data.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
  }
  if (typeof v.body === 'string') {
    const s = v.body.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
  }
  return v;
}

const pts  = $('Fetch point').all().map(i => asJson(i.json));

if (pts.length !== reqs.length) {
  throw new Error(
    `Point lookup returned ${pts.length} responses for ${reqs.length} cities. ` +
    `Rows are paired by position, so a mismatch would attribute one city's ` +
    `forecast to another. Nothing was written. This happens if a response body ` +
    `was a JSON array (n8n splits those into one item per element) - re-run, ` +
    `and if it persists set "Never Error" on Fetch point.`);
}

const now = new Date().toISOString();
// WHAT THE FAILURE ACTUALLY WAS. "37 failed" is a count, not a diagnosis:
// a 403 on the User-Agent, a malformed query and a request that never arrived
// all look identical, and each needs a different fix.
let firstFailure = null;
function describe(req, p) {
  if (!p || Object.keys(p).length === 0) {
    return { city: req.city_key, url: req.point_url, problem: 'empty response' };
  }
  if (p.error) {
    return { city: req.city_key, url: req.point_url, problem: 'request error',
             error: String(p.error).slice(0, 300) };
  }
  return {
    city: req.city_key, url: req.point_url,
    problem: 'no forecastHourly in the /points response and no cached grid',
    http_status: p.status ?? null, title: p.title ?? null,
    detail: typeof p.detail === 'string' ? p.detail.slice(0, 200) : null,
    keys: Object.keys(p).slice(0, 12), body: JSON.stringify(p).slice(0, 400),
  };
}

const out = [], support = [];
let notUS = 0, failed = 0;

for (let i = 0; i < reqs.length; i++) {
  const req = reqs[i], p = pts[i] || {};
  const pp = p.properties || {};
  const is404 = p.status === 404 || String(p.title || '').includes('Not Found');

  if (is404) {
    notUS++;
    support.push({ city_key: req.city_key, nws_supported: false, nws_checked_at: now });
    continue;
  }
  // Prefer the URL NWS published; fall back to the cached grid if this one
  // call failed but an earlier run already resolved the location.
  let url = pp.forecastHourly || null;
  if (!url && req.grid_wfo && req.grid_x != null && req.grid_y != null) {
    url = `https://api.weather.gov/gridpoints/${req.grid_wfo}/${req.grid_x},${req.grid_y}/forecast/hourly`;
  }
  if (!url) { failed++; if (!firstFailure) firstFailure = describe(req, p); continue; }

  // units=si asks for Celsius. The parser still reads temperatureUnit rather
  // than trusting the request - a server that ignores the parameter would
  // otherwise silently store Fahrenheit as Celsius.
  const sep = url.includes('?') ? '&' : '?';
  out.push({ json: {
    city_key: req.city_key,
    grid_wfo: pp.gridId ?? req.grid_wfo ?? null,
    grid_x: pp.gridX ?? req.grid_x ?? null,
    grid_y: pp.gridY ?? req.grid_y ?? null,
    hourly_url: `${url}${sep}units=si`,
  }});
  if (pp.gridId) {
    support.push({
      city_key: req.city_key, nws_supported: true, nws_checked_at: now,
      nws_grid_wfo: pp.gridId, nws_grid_x: pp.gridX ?? null, nws_grid_y: pp.gridY ?? null,
    });
  }
}

if (out.length === 0) {
  const f = firstFailure;
  let why = 'No forecast URLs resolved and no failing response was captured - which should be impossible; report this.';
  if (f) {
    if (f.problem === 'empty response') {
      why = `The "Fetch point" node produced an EMPTY item for this city - no body at all. That is n8n dropping the response, not weather.gov: check that "Fetch point" has Never Error on and is not being rate-limited (lower Batch Size in its options).`;
    } else if (f.problem === 'request error') {
      why = `The /points request never completed: ${f.error}. api.weather.gov was not reached - check n8n's outbound network, or raise the timeout on Fetch point.`;
    } else if (f.http_status === 403) {
      why = `weather.gov answered 403 Forbidden. It REQUIRES a User-Agent identifying your app and refuses generic ones. Open the Config node and make sure user_agent is filled in.`;
    } else if (f.http_status) {
      why = `weather.gov answered ${f.http_status} ${f.title || ''}. ${f.detail || ''}`;
    } else {
      // `data` as the only key is the text-decode failure this workflow was
      // dying of: name it rather than dumping the body and leaving the reader
      // to notice the escaped quotes.
      why = ((f.keys || []).length === 1 && f.keys[0] === 'data')
        ? `weather.gov answered, but n8n decoded the body as TEXT instead of JSON, so there was nothing to read. Open the "Fetch point" node -> Options -> Response -> Response Format and set it to JSON. (api.weather.gov sends Content-Type: application/geo+json, which n8n's autodetect does not recognise as JSON.)`
        : `The /points response had no forecastHourly. Keys: ${(f.keys || []).join(', ')}. Body: ${f.body}`;
    }
  }
  // THE CAUSE GOES FIRST. n8n's error banner shows one line, and one line is
  // what gets copied into a bug report: the previous version led with
  // "37 failed", which is the symptom, and put the reason underneath a blank
  // line where nobody ever saw it. Twice.
  throw new Error(
    why +
    ` [${notUS}/${reqs.length} not US, ${failed}/${reqs.length} failed, nothing written]` +
    (f ? `\n\nFirst failing city: ${f.city}\nURL: ${f.url}` : '') +
    `\n\nThis workflow can also fall back to cities.nws_grid_wfo/x/y, which n8n P1.2 fills in. If P1.2 has never succeeded there is no fallback, so fix P1.2 first - the two usually fail for the same reason.`);
}
// Carry the bookkeeping on the first item; later nodes read it by name.
out[0].json._support = support;
out[0].json._not_us = notUS;
out[0].json._failed = failed;
out[0].json._requested = reqs.length;
return out;

// Hourly periods -> one daily max per local calendar day, per city.
const cfg = $('Config').first().json;
const model = cfg.model_label || 'nws';
const horizon = Number(cfg.max_horizon_days || 7);
const [winFrom, winTo] = String(cfg.peak_window || '12-18').split('-').map(Number);

const reqs = $('Build forecast urls').all().map(i => i.json);
// THE BUG THAT MADE ALL 37 CITIES "FAIL".
// n8n's HTTP node autodetects the response format from Content-Type, and its
// test is `contentType.includes('application/json')`. api.weather.gov answers
// `application/geo+json` (and `application/problem+json` on an error), neither
// of which contains that substring - so every response was decoded as TEXT and
// arrived as `{ data: "{\"properties\":..." }`. No `properties`, no `status`,
// no `title`: not a 404, not an error, just nothing to read. Hence "0 are not
// US, 37 failed" with no detail to report, in both P1.2 and P1.3, forever.
// The Fetch nodes now set responseFormat=json explicitly. This re-parses a
// string body regardless, so the workflow also works on an n8n build that
// names that option differently.
function asJson(v) {
  if (v == null) return {};
  if (typeof v === 'string') {
    const s = v.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
    return { error: 'unparseable body: ' + s.slice(0, 200) };
  }
  if (typeof v !== 'object') return {};
  if (typeof v.data === 'string') {
    const s = v.data.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
  }
  if (typeof v.body === 'string') {
    const s = v.body.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
  }
  return v;
}

const res  = $('Fetch hourly forecast').all().map(i => asJson(i.json));

if (res.length !== reqs.length) {
  throw new Error(
    `Forecast fetch returned ${res.length} responses for ${reqs.length} cities. ` +
    `Rows are paired by position, so a mismatch would attribute one city's ` +
    `forecast to another. Nothing was written.`);
}

const forecasts = [];
let ok = 0, failed = 0, partial = 0;

for (let i = 0; i < reqs.length; i++) {
  const req = reqs[i], r = res[i] || {};
  const props = r.properties || {};
  const periods = Array.isArray(props.periods) ? props.periods : [];

  // A response that names a different gridpoint than we asked for means the
  // pairing slipped. Refuse rather than write one city's weather to another.
  if (props.gridId && req.grid_wfo && props.gridId !== req.grid_wfo) {
    throw new Error(
      `Forecast for grid ${props.gridId} came back where ${req.grid_wfo} ` +
      `(${req.city_key}) was expected. Responses are out of order - nothing written.`);
  }
  if (!periods.length) { failed++; continue; }

  // NWS issuance time, so re-running between issuances updates in place.
  const runAt = props.updateTime || props.generatedAt || new Date().toISOString();

  // startTime carries the gridpoint's own offset, e.g. 2026-09-03T14:00:00-04:00,
  // so slicing the date off gives the LOCAL calendar day with no tz table.
  const byDay = new Map();
  for (const p of periods) {
    if (!p || !p.startTime) continue;
    const day = String(p.startTime).slice(0, 10);
    const hour = Number(String(p.startTime).slice(11, 13));
    let t = Number(p.temperature);
    if (!Number.isFinite(t)) continue;
    if (String(p.temperatureUnit || '').toUpperCase() === 'F') t = (t - 32) * 5 / 9;
    if (!byDay.has(day)) byDay.set(day, { hours: new Set(), max: -Infinity, min: Infinity, at: null, n: 0 });
    const d = byDay.get(day);
    d.hours.add(hour);
    d.n++;
    if (t > d.max) { d.max = t; d.at = p.startTime; }
    if (t < d.min) d.min = t;
  }

  const days = [...byDay.keys()].sort();
  if (!days.length) { failed++; continue; }
  const today = days[0];                       // periods start at the current hour
  let wrote = 0;

  for (const day of days) {
    const d = byDay.get(day);
    // Skip a day whose series misses any of the peak hours: its max would be
    // below the real one, and a too-low max invents divergence out of nothing.
    let covered = true;
    for (let h = winFrom; h <= winTo; h++) if (!d.hours.has(h)) { covered = false; break; }
    if (!covered) { partial++; continue; }

    const lead = Math.round((Date.parse(day + 'T00:00:00Z') - Date.parse(today + 'T00:00:00Z')) / 86400000);
    if (lead < 0 || lead > horizon) continue;

    forecasts.push({
      city_key: req.city_key,
      model,
      run_at: runAt,
      for_date: day,
      lead_days: lead,
      forecast_max_c: Number(d.max.toFixed(2)),
      source: 'api.weather.gov',
      variables: {
        min_c: Number(d.min.toFixed(2)),
        max_at_local: d.at,
        n_hours: d.n,
        peak_window: `${winFrom}-${winTo}`,
        grid: req.grid_wfo ? `${req.grid_wfo}/${req.grid_x},${req.grid_y}` : null,
        issued_at: runAt,
      },
    });
    wrote++;
  }
  if (wrote) ok++; else failed++;
}

return [{ json: {
  forecasts,
  support: reqs[0] && reqs[0]._support ? reqs[0]._support : [],
  n_forecasts: forecasts.length,
  cities_ok: ok, cities_failed: failed, partial_days: partial,
  requested: (reqs[0] && reqs[0]._requested) || reqs.length,
  not_us: (reqs[0] && reqs[0]._not_us) || 0,
} }];

const p = $('Build rows').first().json;
if (p.n_forecasts === 0) {
  // The cause first: n8n shows one line and one line gets pasted into a report.
  const late = new Date().getUTCHours() >= 22;
  throw new Error(
    `Every hourly forecast came back unreadable - 0 forecast days from ` +
    `${p.cities_ok + p.cities_failed} cities, nothing written. ` +
    `If "Fetch hourly forecast" is not set to Response Format = JSON, that is why: ` +
    `api.weather.gov sends application/geo+json and n8n's autodetect decodes it as text.` +
    `\n\n${p.partial_days} day(s) were skipped for not covering the peak window` +
    (late ? ', which is normal this late in the day for TODAY - but tomorrow onwards should still be present, so 0 across the board is a fetch failure, not a late run.' : '.'));
}
return [{ json: p }];

const p = $('Build rows').first().json;
const rows = p.n_forecasts || 0;
const summary =
  `AD4 P1.3: ${rows} NWS forecast day(s) for ${p.cities_ok} cities` +
  (p.not_us ? `, ${p.not_us} not US locations` : '') +
  (p.cities_failed ? `, ${p.cities_failed} failed` : '') +
  (p.partial_days ? `, ${p.partial_days} partial day(s) skipped` : '') + '.';
const status = rows > 0 ? (p.cities_failed ? 'attention' : 'ok') : 'attention';
const detail = { cities_ok: p.cities_ok, cities_failed: p.cities_failed,
                 partial_days: p.partial_days, not_us: p.not_us,
                 requested: p.requested };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P1.3_nws_forecast', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
} }];

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;
